import socket, subprocess, concurrent.futures
def check(ip):
    subprocess.run(["ping","-c1","-W1",ip],capture_output=True)
    for p in (3000,80,8080):
        try:
            s=socket.create_connection((ip,p),timeout=2); s.close()
            return f"{ip}:{p} OPEN"
        except Exception: pass
    return None
targets=[f"172.20.0.{i}" for i in range(1,255)]+[f"172.{n}.0.{i}" for n in (18,19,21) for i in range(1,10)]
with concurrent.futures.ThreadPoolExecutor(100) as ex:
    for r in ex.map(check,targets):
        if r: print(r)
print("scan done")
EOF

